(async () => {
  'use strict';
  const V=window.Vacay, e=V.escape;
  let draft=structuredClone(V.getDraft() || window.VACAY_CONTENT), galleryURLs=[];
  const status=document.querySelector('#studio-status');
  function message(text,error=false){status.textContent=text;status.classList.toggle('error',error);}
  function fillFields(){document.querySelector('#phone').value=draft.contact.phone;document.querySelector('#email').value=draft.contact.email;document.querySelector('#contact-heading-input').value=draft.contact.heading;
    document.querySelector('#copy-fields').innerHTML=draft.story.map((s,i)=>`<div class="copy-scene"><h3>0${i+1} · ${e(s.label.toLowerCase())}</h3><label>Heading<textarea data-story="${i}" data-field="heading">${e(s.heading)}</textarea></label><label>Supporting copy<textarea data-story="${i}" data-field="text">${e(s.text)}</textarea></label></div>`).join('');
  }
  function readFields(){draft.contact.phone=document.querySelector('#phone').value.trim();draft.contact.email=document.querySelector('#email').value.trim();draft.contact.heading=document.querySelector('#contact-heading-input').value.trim();document.querySelectorAll('[data-story]').forEach(el=>draft.story[Number(el.dataset.story)][el.dataset.field]=el.value);document.querySelectorAll('[data-alt]').forEach(el=>{if(el.dataset.alt==='logo')draft.brand.logoAlt=el.value;else draft.images[el.dataset.alt].alt=el.value;});
    for(const type of ['phone','email'])if(draft.contact[type]&&!V.contactValue(type,draft.contact[type]))throw new Error(`Please enter a valid ${type==='phone'?'phone number (7–15 digits, with an optional + country code)':'email address'}, or leave it empty.`);
  }
  async function renderUploads(){galleryURLs.forEach(URL.revokeObjectURL);galleryURLs=[];let uploaded=[];try{uploaded=await V.assets.all();}catch{message('Browser storage is unavailable. You can still edit content.js directly.',true);}
    const grid=document.querySelector('#upload-grid');grid.replaceChildren();
    for(const id of ['logo',...Object.keys(draft.images)]){
      const item=uploaded.find(a=>a.id===id);const info=id==='logo'?{label:'Your existing logo',hint:'Official logo',ratio:'Transparent PNG preferred',tone:'sand',kind:'sun',src:draft.brand.logo}:draft.images[id];
      const card=document.createElement('div');card.className='upload-card';card.dataset.slot=id;card.innerHTML=`<div class="upload-preview"></div><h3>${id==='logo'?'Brand logo':e(info.label)}</h3><label class="upload-pick">Choose a file or drop it here<input type="file" accept="image/jpeg,image/png,image/webp" data-upload="${e(id)}" aria-label="Choose ${e(id)} image"></label><p class="upload-name">${item?e(item.originalName)+' · '+Math.round(item.blob.size/1024)+' KB web copy':'Waiting for your photograph or logo.'}</p><label class="alt-label">Describe this image for accessibility<input data-alt="${e(id)}" value="${e(id==='logo'?draft.brand.logoAlt:info.alt)}" placeholder="What does the photograph show?"></label><button class="remove-image" data-remove="${e(id)}">Restore empty frame</button>`;
      const preview=card.querySelector('.upload-preview');let src=info.src;if(item){src=URL.createObjectURL(item.blob);galleryURLs.push(src);}preview.append(V.photo({...info,src},true));
      card.querySelector('[data-upload]').addEventListener('change',ev=>upload(id,ev.target.files[0]));
      card.querySelector('[data-remove]').addEventListener('click',async()=>{try{readFields();await V.assets.remove(id);if(id==='logo')draft.brand.logo='';else draft.images[id].src='';V.setDraft(draft);await renderUploads();message('Empty frame restored. Save & preview to refresh the site.');}catch(err){message(err.message,true);}});
      card.addEventListener('dragover',ev=>{ev.preventDefault();card.classList.add('is-dragging');});card.addEventListener('dragleave',()=>card.classList.remove('is-dragging'));card.addEventListener('drop',ev=>{ev.preventDefault();card.classList.remove('is-dragging');upload(id,ev.dataTransfer.files[0]);});grid.append(card);
    }
  }
  let processing=0;
  async function upload(id,file){if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)){message('Please choose a JPG, PNG or WebP image.',true);return;}if(file.size>15*1024*1024){message('Please choose an image under 15 MB.',true);return;}
    processing++;message('Preparing your image…');let bitmap;
    try{readFields();bitmap=await createImageBitmap(file);const scale=Math.min(1,2400/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);const type=id==='logo'?'image/png':'image/webp';const blob=await new Promise((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(new Error('Image conversion failed.')),type,.88));await V.assets.put({id,blob,original:file,originalName:file.name,width:canvas.width,height:canvas.height});V.setDraft(draft);await renderUploads();message('Image saved in this browser. Add its description, then save & preview.');}catch(err){message('Could not save this image. '+err.message,true);}finally{bitmap?.close();processing--;}
  }
  function save(){if(processing)throw new Error('Please wait for image processing to finish.');readFields();V.setDraft(draft);}
  document.querySelector('#preview-button').addEventListener('click',()=>{try{save();document.querySelector('#site-preview').src='index.html?preview=1&t='+Date.now();message('Draft saved. The preview below now includes your changes.');}catch(err){message(err.message,true);}});
  document.querySelector('#load-json').addEventListener('click',()=>{try{readFields();document.querySelector('#content-json').value=JSON.stringify(draft,null,2);}catch(err){message(err.message,true);}});
  function validateShape(value,reference,path='content'){
    if(Array.isArray(reference)){if(!Array.isArray(value)||value.length!==reference.length)throw new Error(`${path} must keep its ${reference.length} entries.`);reference.forEach((v,i)=>validateShape(value[i],v,`${path}[${i}]`));}
    else if(reference&&typeof reference==='object'){if(!value||Array.isArray(value)||typeof value!=='object')throw new Error(`${path} must be an object.`);for(const k of Object.keys(reference))validateShape(value[k],reference[k],`${path}.${k}`);}
    else if(typeof value!==typeof reference)throw new Error(`${path} must be ${typeof reference}.`);
  }
  document.querySelector('#apply-json').addEventListener('click',async()=>{try{const parsed=JSON.parse(document.querySelector('#content-json').value);validateShape(parsed,window.VACAY_CONTENT);for(const type of ['phone','email'])if(parsed.contact[type]&&!V.contactValue(type,parsed.contact[type]))throw new Error('Invalid '+type+' in JSON.');draft=parsed;V.setDraft(draft);fillFields();await renderUploads();message('Content applied. Save & preview to review it.');}catch(err){message('Content was not applied: '+err.message,true);}});
  // Tiny ZIP writer, STORE method. No dependencies, uploads, credentials or signed URLs.
  const encoder=new TextEncoder();const crcTable=Uint32Array.from({length:256},(_,n)=>{for(let k=0;k<8;k++)n=n&1?0xedb88320^(n>>>1):n>>>1;return n>>>0;});
  function crc32(bytes){let c=0xffffffff;for(const b of bytes)c=crcTable[(c^b)&255]^(c>>>8);return(c^0xffffffff)>>>0;}
  function header(size){const bytes=new Uint8Array(size);return{bytes,view:new DataView(bytes.buffer)};}
  async function zip(files){const local=[],central=[];let offset=0;for(const f of files){const name=encoder.encode(f.name),data=f.data instanceof Blob?new Uint8Array(await f.data.arrayBuffer()):encoder.encode(f.data),crc=crc32(data),h=header(30+name.length);h.view.setUint32(0,0x04034b50,true);h.view.setUint16(4,20,true);h.view.setUint16(6,0x800,true);h.view.setUint32(14,crc,true);h.view.setUint32(18,data.length,true);h.view.setUint32(22,data.length,true);h.view.setUint16(26,name.length,true);h.bytes.set(name,30);local.push(h.bytes,data);const c=header(46+name.length);c.view.setUint32(0,0x02014b50,true);c.view.setUint16(4,20,true);c.view.setUint16(6,20,true);c.view.setUint16(8,0x800,true);c.view.setUint32(16,crc,true);c.view.setUint32(20,data.length,true);c.view.setUint32(24,data.length,true);c.view.setUint16(28,name.length,true);c.view.setUint32(42,offset,true);c.bytes.set(name,46);central.push(c.bytes);offset+=h.bytes.length+data.length;}const end=header(22),centralSize=central.reduce((n,a)=>n+a.length,0);end.view.setUint32(0,0x06054b50,true);end.view.setUint16(8,files.length,true);end.view.setUint16(10,files.length,true);end.view.setUint32(12,centralSize,true);end.view.setUint32(16,offset,true);return new Blob([...local,...central,end.bytes],{type:'application/zip'});}
  document.querySelector('#export-button').addEventListener('click',async ev=>{const btn=ev.currentTarget;btn.disabled=true;try{save();const data=structuredClone(draft),items=await V.assets.all(),files=[],manifest={version:1,kind:'still-image slots',generatedMedia:false,assets:[]};
      for(const asset of items){const ext=asset.blob.type==='image/png'?'png':asset.blob.type==='image/webp'?'webp':'jpg',path=`assets/uploaded/${asset.id}.${ext}`;if(asset.id==='logo')data.brand.logo=path;else data.images[asset.id].src=path;files.push({name:path,data:asset.blob});files.push({name:`originals/${asset.id}-${asset.originalName.replace(/[^a-zA-Z0-9._-]/g,'_')}`,data:asset.original});manifest.assets.push({id:asset.id,path,width:asset.width,height:asset.height,bytes:asset.blob.size,frameCount:1,poster:path});}
      files.push({name:'content.js',data:'/* Editable Vacay Homes content. Exported from Content Studio. */\nwindow.VACAY_CONTENT = '+JSON.stringify(data,null,2)+';\n'},{name:'assets/uploaded/manifest.json',data:JSON.stringify(manifest,null,2)},{name:'READ-ME.txt',data:'VACAY HOMES CONTENT PACK\nCopy content.js and the assets folder into the website dist folder. Replace the existing content.js. Refresh the site. Keep originals for your records. This export does not publish the website. No generated property imagery is included.\n'});
      const blob=await zip(files),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='vacay-homes-content-pack.zip';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);message('Content pack downloaded. Follow the instructions below to apply it to the website.');
    }catch(err){message('Could not export: '+err.message,true);}finally{btn.disabled=false;}});
  fillFields();await renderUploads();window.__VACAY_STUDIO_READY__=true;window.addEventListener('pagehide',()=>galleryURLs.forEach(URL.revokeObjectURL));
})();
